function serveInOrder(nums) {
  const q = [];                    // JavaScript has no queue: an array...
  let head = 0;                    // ...plus the index of the front
  for (const x of nums) q.push(x);           // enqueue at the back
  const served = [];
  while (head < q.length) {                  // while not empty
    served.push(q[head]);                    // look at the front...
    head++;                                  // ...and dequeue it: O(1), nothing shifts
  }
  return served;                   // the same order the items arrived in
}

List<Integer> serveInOrder(int[] nums) {
    Queue<Integer> q = new ArrayDeque<>();
    for (int x : nums) q.offer(x);       // enqueue at the back
    List<Integer> served = new ArrayList<>();
    while (!q.isEmpty()) {
        served.add(q.peek());            // look at the front
        q.poll();                        // dequeue it
    }
    return served;                       // the same order the items arrived in
}

vector<int> serveInOrder(const vector<int>& nums) {
    queue<int> q;
    for (int x : nums) q.push(x);        // enqueue at the back
    vector<int> served;
    while (!q.empty()) {
        served.push_back(q.front());     // look at the front
        q.pop();                         // dequeue it (pop returns nothing)
    }
    return served;                       // the same order the items arrived in
}

function eliminationOrder(n, k) {
  const q = [];
  let head = 0;                              // the front of the queue
  for (let i = 1; i <= n; i++) q.push(i);    // players 1..n stand in line
  const out = [];
  while (q.length - head > 0) {
    for (let pass = 1; pass < k; pass++) {
      q.push(q[head++]);                     // pass the potato: the front player goes to the back
    }
    out.push(q[head++]);                     // the k-th holder leaves the game
  }
  return out;
}

from collections import deque

def elimination_order(n, k):
    q = deque(range(1, n + 1))               # players 1..n stand in line
    out = []
    while q:
        for _ in range(k - 1):
            q.append(q.popleft())            # pass the potato: the front player goes to the back
        out.append(q.popleft())              # the k-th holder leaves the game
    return out

List<Integer> eliminationOrder(int n, int k) {
    Queue<Integer> q = new ArrayDeque<>();
    for (int i = 1; i <= n; i++) q.offer(i);   // players 1..n stand in line
    List<Integer> out = new ArrayList<>();
    while (!q.isEmpty()) {
        for (int pass = 1; pass < k; pass++) {
            q.offer(q.poll());                 // pass the potato: the front player goes to the back
        }
        out.add(q.poll());                     // the k-th holder leaves the game
    }
    return out;
}

vector<int> eliminationOrder(int n, int k) {
    queue<int> q;
    for (int i = 1; i <= n; i++) q.push(i);   // players 1..n stand in line
    vector<int> out;
    while (!q.empty()) {
        for (int pass = 1; pass < k; pass++) {
            q.push(q.front());                // pass the potato: the front player goes to the back
            q.pop();
        }
        out.push_back(q.front());             // the k-th holder leaves the game
        q.pop();
    }
    return out;
}
